import json

def clear_6x5_components(grid):
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    output = [row[:] for row in grid]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0 and not visited[r][c]:
                # BFS to find component
                cells = []
                stack = [(r, c)]
                visited[r][c] = True

                while stack:
                    cr, cc = stack.pop()
                    cells.append((cr, cc))

                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] != 0 and not visited[nr][nc]:
                                visited[nr][nc] = True
                                stack.append((nr, nc))

                # Check if 6x5 rectangle
                r_min = min(row for row, col in cells)
                r_max = max(row for row, col in cells)
                c_min = min(col for row, col in cells)
                c_max = max(col for row, col in cells)
                height = r_max - r_min + 1
                width = c_max - c_min + 1

                if height == 6 and width == 5:
                    print(f"Clearing 6x5 component at ({r_min},{c_min})")
                    for cr, cc in cells:
                        output[cr][cc] = 0

    return output

